class Solution:
    def maxTastiness(self, price, tastiness, maxAmount, maxCoupons):
        n = len(price)
        dp = [[[0]*(maxCoupons+1) for _ in range(maxAmount+1)] for _ in range(n+1)]
        for i in range(n):
            for a in range(maxAmount+1):
                for c in range(maxCoupons+1):
                    v = dp[i][a][c]
                    if a >= price[i]:
                        v = max(v, dp[i][a-price[i]][c] + tastiness[i])
                        h = price[i] // 2
                        if c > 0 and a >= h:
                            v = max(v, dp[i][a-h][c-1] + tastiness[i])
                    dp[i+1][a][c] = v
        return dp[n][maxAmount][maxCoupons]

